style.css:
@-moz-document domain("youtube.com") {
/* Position the cat image at the bottom-right corner */
    body::after {
        content: "";
        position: fixed;
        bottom: 10px;
        right: 10px;
        width: 100px;
        height: 100px;
        background-image: url("https://placekitten.com/100/100");
        background-size: cover;
        z-index: 9999;
        pointer-events: none; /* Makes the image unclickable */
    }
}
